import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
from collections import deque
def solve(g):
    bg=g[0][0]
    h=len(g); w=len(g[0])
    seen=[[False]*w for _ in range(h)]
    res=[r[:] for r in g]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and not seen[i][j]:
                c=g[i][j]; dq=deque([(i,j)]); seen[i][j]=True; cells=[]
                while dq:
                    a,b=dq.popleft(); cells.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<h and 0<=y<w and g[x][y]==c and not seen[x][y]:
                                seen[x][y]=True; dq.append((x,y))
                rs=[a for a,_ in cells]; cs=[b for _,b in cells]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                if len(cells)==(r1-r0+1)*(c1-c0+1):
                    for a in range(r0+1,r1):
                        for b in range(c0+1,c1):
                            res[a][b]=2
    return res
d=G['Demo pair 1 input']; o=G['Demo pair 1 output']
print(solve(d)==o)
print(json.dumps(solve(G['Test input'])))
